sys_script_include.script:
var SaveRequestItem = Class.create();
SaveRequestItem.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    type: 'SaveRequestItem',
	save: function() {
        var req_item_id = this.getParameter('req_item_id');
        var qa1 = this.getParameter('qa1');
        var qa2 = this.getParameter('qa2');
        var qa3 = this.getParameter('qa3');
        var gr = new GlideRecord('sc_req_item');
        if (gr.get(req_item_id)) {
            gr.variables['office_supply_select'] = qa1;
            gr.variables['quantity'] = qa2;
            gr.variables['description'] = qa3;
			gr.state = 1;
			gr.update();
        }
        return 'OK';
    }
});
